#[allow(
    clippy::absurd_extreme_comparisons,
    clippy::len_zero,
    clippy::redundant_closure
)]
pub fn validate_event_payload(event: &str, payload: &Value) -> bool {
    match event {
        "pmBoardChanged" => {
            serde_json::from_value::<PmBoardChangedPayload>(payload.clone()).is_ok()
                && validate_pm_board_changed_payload(payload)
        }
        "pmAgentChanged" => {
            serde_json::from_value::<PmAgentChangedPayload>(payload.clone()).is_ok()
                && validate_pm_agent_changed_payload(payload)
        }
        "pmCheckChanged" => {
            serde_json::from_value::<PmCheckChangedPayload>(payload.clone()).is_ok()
                && validate_pm_check_changed_payload(payload)
        }
        "pmJiraPulled" => {
            serde_json::from_value::<PmJiraPulledPayload>(payload.clone()).is_ok()
                && validate_pm_jira_pulled_payload(payload)
        }
        "pmSkillsChanged" => {
            serde_json::from_value::<PmSkillsChangedPayload>(payload.clone()).is_ok()
                && validate_pm_skills_changed_payload(payload)
        }
        _ => false,
    }
}
